168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
169	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
170	        if (existingOwnerId != null) {
171	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
172	            if (existingOwner != null) {
173	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
174	            }
175	        }
176	        this.normalizeAddress(ownerFieldsDto);
177	        this.ownerFieldsValidator.validate(ownerFieldsDto);
178	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
182	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
183	        LocalDate serverDate = LocalDate.now();
184	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
185	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
186	        }
187	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
188	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
189	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
190	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
191	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
192	        }
193	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
194	        long ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
195	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
196	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
197	        }
198	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD);
199	        if (owner.getPostcode() != null) {
